type Product = (typeof products)[number];

function buildQuoteLink(cartItems: Product[]) {
  const message =
    cartItems.length > 0
      ? `Hi Codewear, I want a quote for:\n\n${cartItems.map((item, index) => `${index + 1}. ${item.name} - ${item.price}`).join("\n")}\n\nPlease share availability, sizes, and bulk pricing.`
      : "Hi Codewear, I want a custom quote for hospital uniforms and textiles.";

  return `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(message)}`;
}

